, 1.312, 1.672, 1.823, 2.171, 2.566, 2.961, 3.309, 4.029, 4.238, 4.365, 4.458, 4.969, 5.329, 5.41, 5.515]}, {"t": "para", "en": "We also use contractions in everyday speech:", "es": "En la conversación diaria también usamos contracciones, que son formas cortas:", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-01/s3-p2.mp3", "wt": [0, 0.221, 0.511, 0.685, 1.393, 1.521, 1.916]}, {"t": "pairs", "items": [{"a": "I am", "b": "I'm", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-01/s3-c1.mp3", "wt": [0, 0.174, 0.534]}, {"a": "You are", "b": "You're", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-01/s3-c2.mp3", "wt": [0, 0.232, 0.894]}, {"a": "He is", "b": "He's", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-01/s3-c3.mp3", "wt": [0, 0.221, 0.534]}, {"a": "She is", "b": "She's", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-01/s3-c4.mp3", "wt": [0, 0.279, 0.685]}, {"a": "We are", "b": "We're", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-01/s3-c5.mp3", "wt": [0, 0.209, 0.882]}, {"a": "They are", "b": "They're", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-01/s3-c6.mp3", "wt": [0, 0.267, 0.639]}]}, {"t": "examples", "label_en": "Examples", "label_es": "Ejemplos", "items": [{"en": "I'm ready.", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-01/s3-x1.mp3", "wt": [0, 0.244]}, {"en": "She's my friend.", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-01/s3-x2.mp3", "wt": [0, 0.302, 0.453]}, {"en": "We're happy to be here.", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-01/s3-x3.mp3", "wt": [0, 0.267, 0.557, 0.662, 0.848]}]}], "task": {"type": "choose", "q_en": "Which of these is a correct contraction?", "q_e