update public.content_blocks set data = data || jsonb_build_object('v2', $g2${"ep": 2, "topic_en": "Introducing People & Using \"To Be\" with Pronouns", "topic_es": "Presentar personas y «to be» con pronombres", "sections": [{"name_es": "Pronombres + «to be»", "blocks": [{"t": "para", "en": "This week, you're continuing to use the verb \"to be\" (am, is, are), but now with personal pronouns like I, you, he, she to describe people and relationships.", "es": "Esta semana sigues usando el verbo «to be» (am, is, are), ahora con pronombres personales como I, you, he y she, para describir personas y relaciones.", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-02/s1-p1.mp3", "wt": [0, 0.267, 0.488, 0.673, 1.231, 1.347, 1.509, 1.614, 1.904, 2.229, 3.007, 3.506, 3.866, 4.656, 4.853, 5.016, 5.201, 5.608, 6.084, 6.362, 6.885, 7.407, 7.906, 8.684, 8.847, 9.358, 9.752, 9.903]}, {"t": "para", "en": "We use these structures to talk about who someone is:", "es": "Usamos estas estructuras para decir quién es alguien:", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-02/s1-p2.mp3", "wt": [0, 0.232, 0.406, 0.58, 1.045, 1.161, 1.382, 1.625, 1.834, 2.159]}, {"t": "examples", "label_en": "Examples", "label_es": "Ejemplos", "items": [{"en": "I am a man.", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-02/s1-x1.mp3", "wt": [0, 0.174, 0.313, 0.383]}, {"en": "You are a student.", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-02/s1-x2.mp3", "wt": [0, 0.441, 0.673, 0.766]}, {"en": "He is my friend.", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-02/s1-x3.mp3", "wt": [0, 0.197, 0.337, 0.488]}, {"en": "She is a teacher.", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-02/s1-x4.mp3", "wt": [0, 0.372, 0.534, 0.604]}]}], "task": {"type": "choose", "q_en": "Which sentence is correct?", "q_es": "¿Qué oración es correcta?", "options": [{"text": "He are my brother.", "correct": false}, {"text": "He is my brother.", "correct": true}, {"text": "He am my brother.", "correct": false}], "why_en": "He → is.", "why_es": "Con he (él) usamos is.", "q_audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-02/s1-q.mp3", "why_audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-02/s1-why.mp3"}, "key": "s1"}, {"name_es": "Tabla: pronombre + verbo", "blocks": [{"t": "para", "en": "Here's how to match subject pronouns with the correct form of \"to be\".", "es": "Así se combina cada pronombre con la forma correcta de «to be».", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-02/s2-p1.mp3", "wt": [0, 0.313, 0.441, 0.534, 0.813, 1.196, 1.672, 1.858, 2.02, 2.403, 2.74, 2.937, 3.158]}, {"t": "table", "head": ["Pronoun", "Verb", "Example"], "rows": [{"cells": ["I", "am", "I am a student."], "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-tables/ep-02/r1.mp3"}, {"cells": ["You", "are", "You are my friend."], "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-tables/ep-02/r2.mp3"}, {"cells": ["He", "is", "He is a good boy."], "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-tables/ep-02/r3.mp3"}, {"cells": ["She", "is", "She is my mom."], "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-tables/ep-02/r4.mp3"}, {"cells": ["We", "are", "We are family."], "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-tables/ep-02/r5.mp3"}, {"cells": ["They", "are", "They are neighbors."], "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-tables/ep-02/r6.mp3"}]}], "task": {"type": "choose", "q_en": "Which pronoun goes with \"are\"?", "q_es": "¿Qué pronombre va con «are»?", "options": [{"text": "He", "correct": false}, {"text": "I", "correct": false}, {"text": "You", "correct": true}], "why_en": "You → are.", "why_es": "You (tú, usted) → are.", "q_audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-02/s2-q.mp3", "why_audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-02/s2-why.mp3"}, "key": "s2"}, {"name_es": "Contracciones", "blocks": [{"t": "para", "en": "In English, we often use contractions when speaking casually. Here's how:", "es": "En inglés usamos mucho las contracciones al hablar de manera informal. Así se forman:", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-02/s3-p1.mp3", "wt": [0, 0.221, 0.801, 1.033, 1.382, 1.556, 2.218, 2.392, 2.752, 3.785, 4.11]}, {"t": "pairs", "items": [{"a": "I am", "b": "I'm", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-02/s3-c1.mp3", "wt": [0, 0.197, 0.499]}, {"a": "You are", "b": "You're", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-02/s3-c2.mp3", "wt": [0, 0.279, 0.917]}, {"a": "He is", "b": "He's", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-02/s3-c3.mp3", "wt": [0, 0.221, 0.72]}, {"a": "She is", "b": "She's", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-02/s3-c4.mp3", "wt": [0, 0.267, 0.952]}, {"a": "We are", "b": "We're", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-02/s3-c5.mp3", "wt": [0, 0.232, 0.673]}, {"a": "They are", "b": "They're", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-02/s3-c6.mp3", "wt": [0, 0.232, 0.639]}]}, {"t": "examples", "label_en": "Examples", "label_es": "Ejemplos", "items": [{"en": "I'm happy.", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-02/s3-x1.mp3", "wt": [0, 0.255]}, {"en": "She's kind.", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-02/s3-x2.mp3", "wt": [0, 0.29]}, {"en": "You're amazing.", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-02/s3-x3.mp3", "wt": [0, 0.313]}]}], "task": {"type": "choose", "q_en": "What is the contraction of \"She is\"?", "q_es": "¿Cuál es la contracción de «She is»?", "options": [{"text": "She'm", "correct": false}, {"text": "She're", "correct": false}, {"text": "She's", "correct": true}], "why_en": "She is → She's.", "why_es": "She is se contrae como She's.", "q_audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-02/s3-q.mp3", "why_audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-02/s3-why.mp3"}, "key": "s3"}, {"name_es": "Lectura", "blocks": [{"t": "reading", "en": "Read this paragraph while you listen.", "es": "Lee este párrafo mientras lo escuchas.", "sentences": [{"before": "Hi! My name ", "hl": "is", "after": " Mateo."}, {"before": "I ", "hl": "am", "after": " a boy."}, {"before": "This ", "hl": "is", "after": " my sister, Ana."}, {"before": "She ", "hl": "is", "after": " ten years old."}, {"before": "My mom ", "hl": "is", "after": " a teacher."}, {"before": "My dad ", "hl": "is", "after": " at home."}, {"before": "We ", "hl": "are", "after": " a happy family."}], "audio_desc": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-02/s4-d.mp3", "text": "Hi! My name is Mateo. I am a boy. This is my sister, Ana. She is ten years old. My mom is a teacher. My dad is at home. We are a happy family.", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-02/s4-read.mp3", "wt": [0, 1.184, 1.347, 1.533, 1.683, 2.508, 2.635, 2.763, 2.844, 3.831, 4.052, 4.191, 4.342, 5.004, 5.968, 6.177, 6.327, 6.606, 6.85, 7.581, 7.767, 8.069, 8.185, 8.255, 9.056, 9.242, 9.497, 9.613, 9.741, 10.623, 10.902, 11.076, 11.169, 11.494]}], "key": "s4"}, {"name_es": "Phonics", "blocks": [{"t": "phonics", "en": "This week's sounds help you connect letters and people words clearly.", "es": "Los sonidos de esta semana te ayudan a unir las letras con palabras sobre personas.", "families": [{"en": "Letters and example words", "es": "Letras y palabras de ejemplo", "words": [{"w": "A – Apple – Ape", "ipa": "/æ/", "say": "A. Apple. Ape.", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-02/s5-f1w1.mp3", "wt": [0, 0.673, 1.544]}, {"w": "B – Boy", "ipa": "/b/", "say": "B. Boy.", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-02/s5-f1w2.mp3", "wt": [0, 0.267]}, {"w": "C – Cat", "ipa": "/k/", "say": "C. Cat.", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-02/s5-f1w3.mp3", "wt": [0, 0.279]}, {"w": "D – Dog", "ipa": "/d/", "say": "D. Dog.", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-02/s5-f1w4.mp3", "wt": [0, 0.313]}]}, {"en": "Practice tip: say each word clearly, focusing on the first sound.", "es": "Consejo: di cada palabra con claridad, fijándote en el primer sonido.", "words": [{"w": "A is for Apple", "ipa": "/æ/", "say": null, "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-02/s5-f2w1.mp3", "wt": [0, 0.267, 0.406, 0.58]}, {"w": "B is for Boy", "ipa": "/b/", "say": null, "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-02/s5-f2w2.mp3", "wt": [0, 0.197, 0.313, 0.464]}, {"w": "C is for Cat", "ipa": "/k/", "say": null, "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-02/s5-f2w3.mp3", "wt": [0, 0.279, 0.406, 0.557]}, {"w": "D is for Dog", "ipa": "/d/", "say": null, "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-02/s5-f2w4.mp3", "wt": [0, 0.209, 0.325, 0.464]}], "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-02/s5-tip2.mp3", "wt": [0, 0.511, 1.289, 1.567, 1.788, 2.009, 2.67, 3.158, 3.239, 3.355, 3.611]}], "audio_desc": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-02/s5-d.mp3"}], "key": "s5"}], "version": 2, "hl": "\\b(am|is|are|I'm|You're|He's|She's|We're|They're)\\b"}$g2$::jsonb), updated_at = now() where id = '204ed923-33f6-4c07-96c8-794da97e7735' and block_type = 'grammar';
update public.content_blocks set data = data || jsonb_build_object('v2', $g2${"ep": 3, "topic_en": "Talking About Daily Actions with Verbs", "topic_es": "Hablar de tus acciones diarias con verbos", "sections": [{"name_es": "Verbos de tu día", "blocks": [{"t": "para", "en": "This week we focus on using verbs to describe daily actions, especially in the morning and afternoon. You'll continue using \"to be\" and add action verbs like eat, wake up, and go.", "es": "Esta semana usamos verbos para describir acciones diarias, sobre todo en la mañana y en la tarde. Seguirás usando «to be» y sumarás verbos de acción como eat, wake up y go.", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-03/s1-p1.mp3", "wt": [0, 0.279, 0.511, 0.685, 1.091, 1.242, 1.614, 2.09, 2.229, 2.752, 3.193, 4.029, 4.714, 4.83, 4.981, 5.41, 5.573, 6.594, 6.85, 7.512, 7.988, 8.348, 9.102, 9.334, 9.625, 10.054, 10.461, 10.867, 11.389, 11.703, 11.981, 12.237]}, {"t": "examples", "label_en": "Examples", "label_es": "Ejemplos", "items": [{"en": "I eat breakfast.", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-03/s1-x1.mp3", "wt": [0, 0.163, 0.313]}, {"en": "I wake up early.", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-03/s1-x2.mp3", "wt": [0, 0.163, 0.348, 0.488]}, {"en": "I go to work.", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-03/s1-x3.mp3", "wt": [0, 0.174, 0.302, 0.395]}]}], "task": {"type": "choose", "q_en": "Which sentence is correct?", "q_es": "¿Qué oración es correcta?", "options": [{"text": "I eat breakfast.", "correct": true}, {"text": "I eats breakfast.", "correct": false}, {"text": "I am eat breakfast.", "correct": false}], "why_en": "With I, the verb doesn't change: I eat.", "why_es": "Con I, el verbo no cambia: I eat.", "q_audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-03/s1-q.mp3", "why_audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-03/s1-why.mp3"}, "key": "s1"}, {"name_es": "Tabla: rutinas", "blocks": [{"t": "para", "en": "Here are verbs in simple present form for routines.", "es": "Estos son verbos en presente simple para hablar de rutinas.", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-03/s2-p1.mp3", "wt": [0, 0.221, 0.348, 0.65, 0.778, 1.08, 1.405, 1.718, 1.881]}, {"t": "table", "head": ["Subject", "Verb", "Sentence"], "rows": [{"cells": ["I", "wake up", "I wake up early."], "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-tables/ep-03/r1.mp3"}, {"cells": ["You", "take", "You take a shower."], "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-tables/ep-03/r2.mp3"}, {"cells": ["He", "eats", "He eats toast for breakfast."], "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-tables/ep-03/r3.mp3"}, {"cells": ["She", "drinks", "She drinks juice."], "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-tables/ep-03/r4.mp3"}, {"cells": ["We", "cook", "We cook eggs in the morning."], "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-tables/ep-03/r5.mp3"}, {"cells": ["They", "go", "They go to work on time."], "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-tables/ep-03/r6.mp3"}]}], "task": {"type": "choose", "q_en": "Which is correct for \"she\"?", "q_es": "¿Cuál es correcta para «she»?", "options": [{"text": "She eat toast.", "correct": false}, {"text": "She eats toast.", "correct": true}, {"text": "She eating toast.", "correct": false}], "why_en": "He / she / it → add -s: eats.", "why_es": "Con he, she o it, el verbo lleva -s: eats.", "q_audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-03/s2-q.mp3", "why_audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-03/s2-why.mp3"}, "key": "s2"}, {"name_es": "La -s con he, she, it", "blocks": [{"t": "para", "en": "In the present tense, when the subject is he, she, or it, you usually add -s to the verb:", "es": "En presente, cuando el sujeto es he, she o it, normalmente se agrega -s al verbo:", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-03/s3-p1.mp3", "wt": [0, 0.186, 0.302, 0.685, 1.312, 1.509, 1.625, 2.09, 2.287, 2.728, 3.158, 3.39, 4.075, 4.238, 4.586, 4.911, 5.178, 5.294, 5.399]}, {"t": "examples", "label_en": "Examples", "label_es": "Ejemplos", "items": [{"en": "He eats", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-03/s3-x1.mp3", "wt": [0, 0.313]}, {"en": "She drinks", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-03/s3-x2.mp3", "wt": [0, 0.221]}, {"en": "It starts", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-03/s3-x3.mp3", "wt": [0, 0.197]}]}, {"t": "para", "en": "Some verbs change a little more:", "es": "Algunos verbos cambian un poco más:", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-03/s3-p2.mp3", "wt": [0, 0.279, 0.604, 0.859, 0.917, 1.115]}, {"t": "pairs", "items": [{"a": "Go", "b": "Goes", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-03/s3-c1.mp3", "wt": [0, 0.337]}, {"a": "Do", "b": "Does", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-03/s3-c2.mp3", "wt": [0, 0.662]}, {"a": "Have", "b": "Has", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-03/s3-c3.mp3", "wt": [0, 0.755]}]}, {"t": "examples", "label_en": "Examples", "label_es": "Ejemplos", "items": [{"en": "He eats breakfast.", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-03/s3-x4.mp3", "wt": [0, 0.232, 0.476]}, {"en": "She drinks coffee.", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-03/s3-x5.mp3", "wt": [0, 0.209, 0.488]}, {"en": "It starts at 8 AM.", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-03/s3-x6.mp3", "wt": [0, 0.163, 0.453, 0.569, 0.743]}, {"en": "He goes to work.", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-03/s3-x7.mp3", "wt": [0, 0.209, 0.453, 0.592]}, {"en": "She does her homework.", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-03/s3-x8.mp3", "wt": [0, 0.209, 0.372, 0.476]}, {"en": "It has four wheels.", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-03/s3-x9.mp3", "wt": [0, 0.186, 0.395, 0.639]}]}], "task": {"type": "choose", "q_en": "Which is correct?", "q_es": "¿Cuál es correcta?", "options": [{"text": "He go to work.", "correct": false}, {"text": "He goes to work.", "correct": true}, {"text": "He going to work.", "correct": false}], "why_en": "He → goes.", "why_es": "Con he, go cambia a goes.", "q_audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-03/s3-q.mp3", "why_audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-03/s3-why.mp3"}, "key": "s3"}, {"name_es": "Lectura", "blocks": [{"t": "reading", "en": "Read this paragraph while you listen.", "es": "Lee este párrafo mientras lo escuchas.", "sentences": [{"before": "Hi, I'm Lily. I ", "hl": "wake up", "after": " early every day."}, {"before": "I ", "hl": "eat", "after": " eggs and toast for breakfast."}, {"before": "Then, I ", "hl": "take", "after": " a shower and go to work."}, {"before": "After work, I ", "hl": "read", "after": " a book or watch TV."}, {"before": "I ", "hl": "like", "after": " my day!"}], "audio_desc": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-03/s4-d.mp3", "text": "Hi, I'm Lily. I wake up early every day. I eat eggs and toast for breakfast. Then, I take a shower an