update public.content_blocks set data = data || jsonb_build_object('v2', $g2${"ep": 5, "topic_en": "Expressing needs with \"need to\" and the present continuous", "topic_es": "Decir lo que necesitas con «need to» y el presente continuo", "sections": [{"name_es": "Ordena la frase: need to", "blocks": [{"t": "para", "en": "We use \"need to\" plus a verb to talk about things that are necessary for our body, health, or feelings.", "es": "Usamos «need to» + un verbo para hablar de lo que necesitamos para el cuerpo, la salud o las emociones.", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-05/s1-p1.mp3", "wt": [0, 0.255, 0.546, 0.929, 1.44, 1.707, 1.788, 2.067, 2.171, 2.38, 2.624, 2.914, 3.042, 3.228, 3.773, 3.936, 4.098, 4.911, 5.399, 5.631]}, {"t": "examples", "label_en": "Examples", "label_es": "Ejemplos", "items": [{"en": "I need to sleep.", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-05/s1-x1.mp3", "wt": [0, 0.163, 0.348, 0.453]}, {"en": "You need to drink water.", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-05/s1-x2.mp3", "wt": [0, 0.255, 0.464, 0.546, 0.789]}, {"en": "We need to breathe clean air.", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-05/s1-x3.mp3", "wt": [0, 0.186, 0.348, 0.43, 0.673, 0.906]}]}], "task": {"type": "build", "sentence": "I need to drink water.", "en": "Put the words in order.", "es": "Ordena las palabras para formar la oración.", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-05/s1-build.mp3", "audio_inst": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-05/s1-bi.mp3", "wt": [0, 0.174, 0.325, 0.406, 0.65]}, "key": "s1"}, {"name_es": "Need to y -ing", "blocks": [{"t": "para", "en": "This week, you're learning how to express what you need using \"need to\" and how to talk about what you're doing with the present continuous (am, is, are + verb-ing).", "es": "Esta semana aprendes a decir lo que necesitas con «need to» y a hablar de lo que estás haciendo con el presente continuo (am, is, are + verbo con -ing).", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-05/s2-p1.mp3", "wt": [0, 0.313, 0.964, 1.173, 1.474, 1.591, 1.707, 2.229, 2.403, 2.601, 3.1, 3.529, 3.947, 4.772, 5.004, 5.155, 5.259, 5.492, 5.689, 5.828, 6.049, 6.432, 6.606, 6.745, 7.198, 8.046, 8.998, 9.729, 10.403, 11.122]}, {"t": "examples", "label_en": "Examples", "label_es": "Ejemplos", "items": [{"en": "I need to rest.", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-05/s2-x1.mp3", "wt": [0, 0.151, 0.313, 0.418]}, {"en": "She is washing her face.", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-05/s2-x2.mp3", "wt": [0, 0.209, 0.348, 0.673, 0.778]}, {"en": "They are wearing jackets.", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-05/s2-x3.mp3", "wt": [0, 0.221, 0.337, 0.615]}]}], "task": {"type": "choose", "q_en": "Which sentence is correct?", "q_es": "¿Qué oración es correcta?", "options": [{"text": "I need sleep.", "correct": false}, {"text": "I need to sleep.", "correct": true}, {"text": "I am sleep.", "correct": false}, {"text": "I need to sleeping.", "correct": false}], "why_en": "need to + verb: I need to sleep.", "why_es": "need to + verbo, sin -ing: I need to sleep.", "q_audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-05/s2-q.mp3", "why_audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-05/s2-why.mp3"}, "key": "s2"}, {"name_es": "Completa las frases", "blocks": [{"t": "para", "en": "Choose the word that best completes each sentence.", "es": "Elige la palabra que completa mejor cada oración.", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-05/s3-p1.mp3", "wt": [0, 0.395, 0.5