update public.content_blocks set data = data || jsonb_build_object('v2', $g2${"ep": 8, "topic_en": "Simple Present vs. Present Progressive", "topic_es": "Presente simple o presente progresivo", "sections": [{"name_es": "Ordena la frase", "blocks": [{"t": "para", "en": "We use the present progressive to describe what is happening now, and the simple present to describe routines or facts.", "es": "Usamos el presente progresivo para lo que está pasando ahora, y el presente simple para rutinas o hechos.", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-08/s1-p1.mp3", "wt": [0, 0.255, 0.534, 0.673, 1.068, 1.788, 2.159, 2.659, 2.81, 2.914, 3.32, 4.18, 4.435, 4.551, 4.888, 5.306, 5.41, 6.026, 6.676, 6.943]}, {"t": "examples", "label_en": "Examples", "label_es": "Ejemplos", "items": [{"en": "She is watching a movie now.", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-08/s1-x1.mp3", "wt": [0, 0.244, 0.383, 0.697, 0.755, 1.01]}, {"en": "He works at the office every day.", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-08/s1-x2.mp3", "wt": [0, 0.232, 0.534, 0.627, 0.766, 1.091, 1.3]}, {"en": "They are playing soccer right now.", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-08/s1-x3.mp3", "wt": [0, 0.232, 0.372, 0.755, 1.126, 1.324]}]}], "task": {"type": "build", "sentence": "She is watching a movie now.", "en": "Put the words in order.", "es": "Ordena las palabras para formar la oración.", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-08/s1-x1.mp3", "audio_inst": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-08/s1-bi.mp3", "wt": [0, 0.244, 0.383, 0.697, 0.755, 1.01]}, "key": "s1"}, {"name_es": "Ahora o siempre", "blocks": [{"t": "para", "en": "Listen and choose the correct sentence using either the simple present or the present progressive.", "es": "Escucha y elige la oración correcta, en presente simple o en presente progresivo.", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-08/s2-p1.mp3", "wt": [0, 0.917, 1.207, 1.8, 1.974, 2.531, 3.262, 3.646, 3.936, 4.087, 4.47, 5.445, 5.654, 5.805, 6.56]}, {"t": "examples", "label_en": "Examples", "label_es": "Ejemplos", "items": [{"en": "I am brushing my teeth.", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-08/s2-x1.mp3", "wt": [0, 0.139, 0.244, 0.569, 0.697]}, {"en": "She watches TV every evening.", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-08/s2-x2.mp3", "wt": [0, 0.232, 0.662, 1.045, 1.324]}, {"en": "They are playing soccer now.", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-08/s2-x3.mp3", "wt": [0, 0.221, 0.348, 0.697, 1.068]}]}], "task": {"type": "choose", "q_en": "Which sentence is correct?", "q_es": "¿Qué oración es correcta?", "options": [{"text": "I brush my teeth now.", "correct": false}, {"text": "I brushing my teeth.", "correct": false}, {"text": "I am brush my teeth.", "correct": false}, {"text": "I am brushing my teeth.", "correct": true}], "why_en": "Right now → am + verb-ing.", "why_es": "Ahora mismo → am + verbo con -ing.", "q_audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-08/s2-q.mp3", "why_audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-08/s2-why.mp3"}, "key": "s2"}, {"name_es": "Completa las frases", "blocks": [{"t": "para", "en": "Choose the word that best completes each sentence.", "es": "Elige la palabra que completa mejor cada oración.", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-08/s3-p1.mp3", "wt": [0, 0.337, 0.441, 0.685, 0.894, 1.231, 1.73, 1.985]}], "task": {"type": "fill", "items": [{"before": "She is", "after": "a movie now.", "options": ["watching", "watches"], "correct": "watching", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-08/s1-x1.mp3", "wt": [0, 0.244, 0.383, 0.697, 0.755, 1.01]}, {"before": "Joe", "after": "movies every Saturday.", "options": ["watches", "watching"], "correct": "watches", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-08/s3-f2.mp3", "wt": [0, 0.267, 0.615, 0.906, 1.126]}]}, "key": "s3"}, {"name_es": "Escucha y elige", "blocks": [], "task": {"type": "hear_pick", "sentence": "They are playing soccer.", "word": "playing", "files": ["storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/896c5b60a1_8ac12be9b_gram_ep_08_listening_select_inverted_1.mp3", "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/15270526d4_fee418f75_gram_ep_08_listening_select_inverted_2.mp3", "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/58fdecc26e_166b5544b_gram_ep_08_listening_select_inverted_3.mp3"], "correct": 1, "en": "Listen to each option and choose the word that completes the sentence.", "es": "Escucha cada opción y elige la palabra que completa la oración.", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-08/s4-sent.mp3", "audio_inst": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-08/s4-hi.mp3", "wt": [0, 0.232, 0.36, 0.708]}, "key": "s4"}, {"name_es": "Lectura", "blocks": [{"t": "reading", "en": "Read these five sentences and listen. Notice the verb tense.", "es": "Lee estas cinco oraciones mientras las escuchas. Fíjate en el tiempo del verbo.", "sentences": [{"before": "I ", "hl": "wake up", "after": " at 7 a.m."}, {"before": "We ", "hl": "are playing", "after": " soccer right now."}, {"before": "She ", "hl": "doesn't eat", "after": " moronga."}, {"before": "He ", "hl": "isn't dancing", "after": " salsa."}, {"before": "They ", "hl": "don't drink", "after": " beer."}], "audio_desc": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-08/s5-d.mp3", "text": "I wake up at 7 a.m. We are playing soccer right now. She doesn't eat moronga. He isn't dancing salsa. They don't drink beer.", "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-08/s5-read.mp3", "wt": [0, 0.197, 0.406, 0.534, 0.673, 0.94, 1.277, 1.44, 1.579, 1.962, 2.38, 2.543, 3.297, 3.471, 3.727, 3.889, 4.807, 4.981, 5.19, 5.515, 6.235, 6.42, 6.583, 6.815]}], "key": "s5"}, {"name_es": "Phonics", "blocks": [{"t": "phonics", "en": "This is how you say it. Listen and repeat.", "es": "Así se dice. Escucha y repite.", "families": [{"en": "Vowel sound \"A\"", "es": "Sonido de la vocal «A»", "words": [{"w": "Cat", "ipa": "/æ/", "say": null, "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-08/s6-f1w1.mp3", "wt": [0]}, {"w": "Make", "ipa": "/eɪ/", "say": null, "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-08/s6-f1w2.mp3", "wt": [0]}]}, {"en": "Vowel sound \"E\"", "es": "Sonido de la vocal «E»", "words": [{"w": "Bed", "ipa": "/ɛ/", "say": null, "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-08/s6-f2w1.mp3", "wt": [0]}, {"w": "See", "ipa": "/i/", "say": null, "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-08/s6-f2w2.mp3", "wt": [0]}]}, {"en": "Vowel sound \"I\"", "es": "Sonido de la vocal «I»", "words": [{"w": "Sit", "ipa": "/ɪ/", "say": null, "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-08/s6-f3w1.mp3", "wt": [0]}, {"w": "Like", "ipa": "/aɪ/", "say": null, "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-08/s6-f3w2.mp3", "wt": [0]}]}, {"en": "Vowel sound \"O\"", "es": "Sonido de la vocal «O»", "words": [{"w": "Hot", "ipa": "/ɑ/", "say": null, "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-08/s6-f4w1.mp3", "wt": [0]}, {"w": "Go", "ipa": "/oʊ/", "say": null, "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-08/s6-f4w2.mp3", "wt": [0]}]}, {"en": "Vowel sound \"U\"", "es": "Sonido de la vocal «U»", "words": [{"w": "Cut", "ipa": "/ʌ/", "say": null, "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-08/s6-f5w1.mp3", "wt": [0]}, {"w": "Use", "ipa": "/ju/", "say": null, "audio": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-08/s6-f5w2.mp3", "wt": [0]}]}], "audio_desc": "storage://course-media/0928ee68-d20b-4cdf-8e4b-5489ce16b4a3/grammar-v2/ep-08/s6-d.mp3"}], "key": "s6"}], "version": 2, "hl": "\\b(am|is|are|\\w+ing|works|watches)\\b"}$g2$::jsonb), updated_at = now() where id = '04b9ec25-01d1-432a-8bf0-1ce3db2e0312' and block_type = 'grammar';
